  ('72166166-41c0-508b-948f-e7c3738946bc'::uuid, 'ana.garcia@ejemplo.mx', 'BICYCLE'::transport_mode, 'COMPLETED'::trip_status, 'GPS'::trip_source, '2026-11-13T14:00:00+00:00'::timestamptz, 25, NULL::vehicle_type, NULL::smallint, 'LINESTRING(-100.389000 20.593000, -100.360000 20.585000, -100.330000 20.575000)', 'ecb21aa0-3066-58eb-b832-4fb42ec5b141'::uuid, '796432aa-062a-59ff-9daa-dbd88e6df49b'::uuid)
),
calc AS (
  SELECT s.*, u.id AS user_id,
         ST_GeomFromText(s.wkt, 4326) AS route,
         ST_Length(ST_GeomFromText(s.wkt, 4326)::geography) / 1000.0 AS km,
         CASE WHEN s.mode IN ('CAR', 'CARPOOL')
              THEN COALESCE(s.vehicle_type, p.default_vehicle_type, 'SEDAN') END AS vt,
         CASE WHEN s.mode = 'CAR' THEN COALESCE(s.occupants, 1)
              WHEN s.mode = 'CARPOOL' THEN COALESCE(s.occupants, 2) END AS occ,
         ref.grams_per_km AS ref_g, ef.grams_per_km AS mode_g
  FROM src s
  JOIN users u ON u.email = s.email
  LEFT JOIN user_preferences p ON p.user_id = u.id
  JOIN vehicle_types ref ON ref.code = COALESCE(p.default_vehicle_type, 'SEDAN')
  JOIN emission_factors ef ON ef.mode = s.mode
),
co2 AS (
  SELECT c.*,
         CASE WHEN c.vt IS NOT NULL THEN v.grams_per_km / c.occ ELSE c.mode_g END AS factor,
         CASE WHEN c.vt IS NOT NULL THEN c.km * v.grams_per_km / c.occ ELSE c.km * c.mode_g END AS emitted,
         CASE WHEN c.vt IS NOT NULL THEN c.km * v.grams_per_km - c.km * v.grams_per_km / c.occ
              ELSE GREATEST(0, c.km * (c.ref_g - c.mode_g)) END AS saved
  FROM calc c LEFT JOIN vehicle_types v ON v.code = c.vt
)
                   emission_factor_g_per_km, co2_emitted_g, co2_saved_g, source, points, recurrence_id,
                   vehicle_type, occupants, created_at, updated_at)
SELECT id, user_id, client_trip_id, mode, status, started_at, started_at + make_interval(mins => minutes),
       round((km * 1000)::numeric, 1), minutes * 60, route, round(factor::numeric, 3), round(emitted::numeric, 2),
       round(saved::numeric, 2), source,
       CASE WHEN status = 'COMPLETED' THEN floor(saved / 100)::int ELSE 0 END, recurrence_id, vt, occ,
       started_at + make_interval(mins => minutes), started_at + make_interval(mins => minutes)
FROM co2;

-- ---------------------------------------------------------------------------
-- 7. Logros obtenidos: misma regla que el backend (métrica ≥ umbral), en SQL
-- ---------------------------------------------------------------------------
WITH totals AS (
  SELECT user_id, count(*) AS trips, sum(distance_m) AS dist, sum(co2_saved_g) AS saved,
         count(DISTINCT mode) AS modes, max(ended_at) AS last_trip
  FROM trips WHERE status = 'COMPLETED' GROUP BY user_id
)
SELECT gen_random_uuid(), t.user_id, a.id, a.bonus_points, t.last_trip
FROM totals t JOIN achievements a ON a.is_active AND
  CASE a.criterion WHEN 'TRIPS_COUNT' THEN t.trips WHEN 'DISTANCE_M' THEN t.dist
                   WHEN 'CO2_SAVED_G' THEN t.saved ELSE t.modes END >= a.threshold;

-- ---------------------------------------------------------------------------
-- 8. Notificaciones: una por logro obtenido + avisos del sistema
-- ---------------------------------------------------------------------------
SELECT md5(ua.user_id::text || a.code)::uuid, ua.user_id, 'ACHIEVEMENT_UNLOCKED', '¡Nuevo logro!',
       'Desbloqueaste «' || a.name || '»', jsonb_build_object('achievement_code', a.code),
       CASE WHEN a.threshold < 5 THEN ua.awarded_at + interval '1 day' END, ua.awarded_at
FROM user_achievements ua JOIN achievements a ON a.id = ua.achievement_id;

SELECT md5(u.id::text || 'bienvenida')::uuid, u.id, 'SYSTEM', 'Bienvenida a EcoMove Querétaro',
       'Cada viaje cuenta: registra tus traslados para ver tu impacto.', '{}'::jsonb, u.created_at
FROM users u WHERE u.role = 'USER';

SELECT md5(t.user_id::text || 'resumen-2026-11-09')::uuid, t.user_id, 'WEEKLY_SUMMARY', 'Tu resumen semanal',
       'Esta semana evitaste ' || round(sum(t.co2_saved_g)) || ' g de CO2.',
       jsonb_build_object('trips', count(*), 'co2_saved_g', round(sum(t.co2_saved_g))), timestamptz '2026-11-09 15:00Z'
FROM trips t WHERE t.status = 'COMPLETED' AND t.started_at >= '2026-11-02' AND t.started_at < '2026-11-09'
GROUP BY t.user_id;

-- ---------------------------------------------------------------------------
-- 9. Reportes ciudadanos ficticios
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 10. Auditoría e informes ficticios
-- ---------------------------------------------------------------------------
SELECT '9ada45a6-18f6-5a0d-9ec2-445feaff01e0', 'co2_by_mode', 'csv', '{"from": null, "to": null}'::jsonb, count(*),
       convert_to('mode,trips_count,co2_saved_g' || chr(10) ||
                  string_agg(mode || ',' || n || ',' || saved, chr(10) ORDER BY mode), 'UTF8'),
       '42231539-2f68-5e5d-ad4b-20894c5170c2', timestamptz '2026-11-10 17:00Z'
FROM (SELECT mode::text AS mode, count(*) AS n, round(sum(co2_saved_g)::numeric, 2) AS saved
      FROM trips WHERE status = 'COMPLETED' GROUP BY mode) m;

COMMIT;
